-- =====================================================================
-- ai-ssh 本地 H2 库建表脚本（local profile）
--
-- 与 docs/dev-ops/mysql/sql/init.sql 的 MySQL DDL 对齐，差异仅限方言：
--   1) 自增主键：BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY
--   2) 长文本：CLOB（MySQL 的 TEXT / LONGTEXT）
--   3) 时间：TIMESTAMP DEFAULT CURRENT_TIMESTAMP；不写 ON UPDATE
--      （H2 无 MySQL 的 ON UPDATE 语义，updated_at 由 Java 写路径显式维护，
--        见 ChatHistoryRepository / LongTermMemoryRepository / SshConnectionRepository）
--   4) 不写 ENGINE / CHARSET / COLLATE；索引改为独立 CREATE INDEX 语句
--   5) 全部 IF NOT EXISTS：本地文件库跨重启重复初始化必须幂等
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. SSH 连接配置表
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS ssh_connection (
    id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    connection_id     VARCHAR(64)  NOT NULL,
    connection_name   VARCHAR(128) NOT NULL,
    host              VARCHAR(255) NOT NULL,
    port              INT          NOT NULL DEFAULT 22,
    username          VARCHAR(128) NOT NULL,
    auth_type         TINYINT      NOT NULL DEFAULT 1,
    password          VARCHAR(512),
    private_key       CLOB,
    encrypted         TINYINT      NOT NULL DEFAULT 1,
    status            TINYINT      NOT NULL DEFAULT 0,
    user_id           VARCHAR(64)  NOT NULL DEFAULT 'default',
    group_name        VARCHAR(64),
    tags              VARCHAR(512),
    remark            VARCHAR(512),
    favorite          TINYINT      NOT NULL DEFAULT 0,
    last_connected_at TIMESTAMP,
    created_at        TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at        TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted           TINYINT      NOT NULL DEFAULT 0
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_ssh_connection_connection_id ON ssh_connection (connection_id);
CREATE INDEX IF NOT EXISTS idx_ssh_connection_user_id        ON ssh_connection (user_id);
CREATE INDEX IF NOT EXISTS idx_ssh_connection_user_group     ON ssh_connection (user_id, group_name);
CREATE INDEX IF NOT EXISTS idx_ssh_connection_user_favorite  ON ssh_connection (user_id, favorite);
CREATE INDEX IF NOT EXISTS idx_ssh_connection_status         ON ssh_connection (status);
CREATE INDEX IF NOT EXISTS idx_ssh_connection_created_at     ON ssh_connection (created_at);

-- ---------------------------------------------------------------------
-- 2. SSH 连接高级配置表
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS ssh_connection_config (
    id                    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    connection_id         VARCHAR(64) NOT NULL,
    connect_timeout       INT         NOT NULL DEFAULT 10,
    keepalive_interval    INT         NOT NULL DEFAULT 60,
    startup_command       VARCHAR(512),
    compression           TINYINT     NOT NULL DEFAULT 0,
    strict_host_key_check TINYINT     NOT NULL DEFAULT 1,
    known_hosts           CLOB,
    updated_at            TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_ssh_connection_config_connection_id ON ssh_connection_config (connection_id);

-- ---------------------------------------------------------------------
-- 3. 对话会话表
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS chat_session (
    id            VARCHAR(64)  NOT NULL PRIMARY KEY,
    agent_id      VARCHAR(64)  NOT NULL,
    user_id       VARCHAR(64)  NOT NULL,
    title         VARCHAR(200) DEFAULT '新会话',
    message_count INT          NOT NULL DEFAULT 0,
    created_at    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_chat_session_user_agent ON chat_session (user_id, agent_id);
CREATE INDEX IF NOT EXISTS idx_chat_session_updated_at ON chat_session (updated_at);

-- ---------------------------------------------------------------------
-- 4. 对话消息表
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS chat_message (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    session_id   VARCHAR(64)  NOT NULL,
    role         VARCHAR(20)  NOT NULL,
    content      CLOB,
    tool_name    VARCHAR(100),
    tool_call_id VARCHAR(100),
    priority     VARCHAR(20)  NOT NULL DEFAULT 'MEDIUM',
    token_count  INT          NOT NULL DEFAULT 0,
    created_at   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_chat_message_session ON chat_message (session_id, id);

-- ---------------------------------------------------------------------
-- 5. 对话里程碑表
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS chat_milestone (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    session_id VARCHAR(64) NOT NULL,
    type       VARCHAR(30) NOT NULL,
    content    CLOB,
    created_at TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_chat_milestone_session ON chat_milestone (session_id, id);

-- ---------------------------------------------------------------------
-- 6. 长期记忆表
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS long_term_memory (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id     VARCHAR(64)   NOT NULL,
    session_id  VARCHAR(64),
    memory_type VARCHAR(50)   NOT NULL,
    memory_key  VARCHAR(128)  NOT NULL,
    content     CLOB,
    keywords    VARCHAR(512),
    source_role VARCHAR(20),
    confidence  DECIMAL(5, 2) NOT NULL DEFAULT 0.50,
    hit_count   INT           NOT NULL DEFAULT 1,
    created_at  TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at  TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_long_term_memory_user_type_key
    ON long_term_memory (user_id, memory_type, memory_key);
CREATE INDEX IF NOT EXISTS idx_long_term_memory_user_time ON long_term_memory (user_id, updated_at);

-- ---------------------------------------------------------------------
-- 7. 操作审计日志表
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS operation_audit_log (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id         VARCHAR(64)   NOT NULL DEFAULT 'default',
    connection_id   VARCHAR(64),
    connection_name VARCHAR(128),
    action          VARCHAR(64)   NOT NULL,
    resource        VARCHAR(1024),
    detail          VARCHAR(2048),
    risk_level      VARCHAR(16)   NOT NULL DEFAULT 'LOW',
    success         TINYINT       NOT NULL DEFAULT 1,
    duration_ms     BIGINT        NOT NULL DEFAULT 0,
    client_ip       VARCHAR(64),
    created_at      TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_audit_log_user_time       ON operation_audit_log (user_id, created_at);
CREATE INDEX IF NOT EXISTS idx_audit_log_connection_time ON operation_audit_log (connection_id, created_at);
CREATE INDEX IF NOT EXISTS idx_audit_log_action_time     ON operation_audit_log (action, created_at);

-- ---------------------------------------------------------------------
-- 8. 会话任务态表（chat_task_state，按 ChatTaskStatePO 推断；
--    MySQL 侧由同结构脚本维护，本地库直接按 PO 字段建表）
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS chat_task_state (
    session_id          VARCHAR(64) NOT NULL PRIMARY KEY,
    root_intent         VARCHAR(64),
    task_description    CLOB,
    steps               CLOB,
    current_step_index  INT         NOT NULL DEFAULT 0,
    completed           TINYINT     NOT NULL DEFAULT 0,
    last_feedback_failed TINYINT    NOT NULL DEFAULT 0,
    updated_at          TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP
);
